add_filter( 'woocommerce_states', 'perfectpixel_limit_states' );

function perfectpixel_limit_states( $states ) {
	$country = strtoupper( '{{limit_states_country}}' );
	$keep    = array_filter( array_map( 'trim', explode( ',', strtoupper( '{{limit_states_codes}}' ) ) ) );
	if ( isset( $states[ $country ] ) && $keep && ! is_admin() ) {
		$states[ $country ] = array_intersect_key( $states[ $country ], array_flip( $keep ) );
	}
	return $states;
}
